content:
Here is a complete, idiomatic Terraform implementation that satisfies your canonical scenario while explicitly fixing the **circular dependency** and **`count` vs `for_each`** errors. The code is structured for production use with clear separation of concerns.

### 📁 Project Structure
```
terraform/
├── main.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
└── prod.tfvars
```

---

### 📜 `variables.tf`
```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws  = { source = "hashicorp/aws", version = "~> 5.0" }
    sops = { source = "carpetdata/sops", version = "~> 0.4" }
  }
}

provider "aws" {
  region = var.region
}

variable "environment" {
  description = "Target environment (dev or prod)"
  type        = string
  default     = terraform.workspace
}

variable "region" {
  description = "AWS region for deployment"
  type        = string
}

variable "db_sops_file" {
  description = "Path to SOPS-encrypted DB credentials file"
  type        = string
  sensitive   = true
}

variable "s3_replication_destination_bucket" {
  description = "ARN of destination bucket for prod cross-region replication"
  type        = string
  default     = ""
}

locals {
  is_prod = var.environment == "prod"

  # Environment-specific sizing
  eks_node_count    = local.is_prod ? 4 : 2
  eks_node_instance = local.is_prod ? "t3.large" : "t3.medium"
  rds_instance_class = local.is_prod ? "db.t3.medium" : "db.t3.micro"
}
```

---

### 📜 `main.tf`
```hcl
# =============================================================================
# NETWORKING (Minimal required for RDS/EKS/ALB)
# =============================================================================
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  tags = { Name = "${var.environment}-vpc" }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.${count.index + 10}.0/24"
  availability_zone       = "${var.region}${count.index == 0 ? "a" : "b"}"
  map_public_ip_on_launch = false
  tags = { Name = "${var.environment}-private-${count.index + 1}" }
}

resource "aws_security_group" "rds" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.eks_nodes.id]
  }
  egress { from_port = 0; to_port = 0; protocol = "-1"; cidr_blocks = ["0.0.0.0/0"] }
  tags = { Name = "${var.environment}-rds-sg" }
}

resource "aws_security_group" "eks_nodes" {
  vpc_id = aws_vpc.main.id
  egress { from_port = 0; to_port = 0; protocol = "-1"; cidr_blocks = ["0.0.0.0/0"] }
  tags = { Name = "${var.environment}-eks-nodes-sg" }
}

resource "aws_db_subnet_group" "main" {
  name       = "${var.environment}-db-subnet"
  subnet_ids = aws_subnet.private[*].id
}

# =============================================================================
# S3 BUCKET (Assets)
# =============================================================================
resource "aws_s3_bucket" "assets" {
  bucket = "${var.environment}-app-assets-${var.region}"
  tags   = { Environment = var.environment }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Prod-only cross-region replication
resource "aws_s3_bucket_replication_configuration" "assets" {
  count  = local.is_prod ? 1 : 0
  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.s3_replication[0].arn

  replication_rule {
    status = "Enabled"
    destination {
      bucket = var.s3_replication_destination_bucket
      encryption_configuration {
        replica_kms_key_id = null # Uses destination bucket default
      }
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  count = local.is_prod ? 1 : 0
  name  = "${var.environment}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action   = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  count  = local.is_prod ? 1 : 0
  role   = aws_iam_role.s3_replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Effect = "Allow", Action = ["s3:GetReplicationConfiguration", "s3:ListBucket"], Resource = [aws_s3_bucket.assets.arn] },
      { Effect = "Allow", Action = ["s3:GetObjectVersionForReplication", "s3:GetObjectVersionAcl", "s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"], Resource = "${aws_s3_bucket.assets.arn}/*" }
    ]
  })
}

# =============================================================================
# RDS POSTGRESQL
# =============================================================================
resource "aws_db_instance" "app" {
  identifier           = "${var.environment}-app-db"
  engine               = "postgres"
  engine_version       = "15.4"
  instance_class       = local.rds_instance_class
  allocated_storage    = 20
  db_name              = "appdb"
  username             = "dbadmin"
  password             = data.sops_file.db_secret.data["db_password"]
  skip_final_snapshot  = true
  publicly_accessible  = false
  deletion_protection  = true
  backup_retention_period = 7
  multi_az             = local.is_prod
  storage_encrypted    = local.is_prod
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  tags = { Environment = var.environment }
}

# =============================================================================
# EKS CLUSTER & NODE GROUPS
# =============================================================================
resource "aws_iam_role" "eks_cluster" {
  name = "${var.environment}-eks-cluster-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{ Effect = "Allow", Principal = { Service = "eks.amazonaws.com" }, Action = "sts:AssumeRole" }]
  })
}

resource "aws_eks_cluster" "main" {
  name     = "${var.environment}-eks-cluster"
  role_arn = aws_iam_role.eks_cluster.arn
  version  = "1.28"
  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.eks_nodes.id]
  }
  tags = { Environment = var.environment }
}

# 🔧 FIX: count/for_each error
# Using `for_each` with a map provides stable resource addressing.
# `count` fails when items are added/removed mid-index, breaking downstream references.
resource "aws_eks_node_group" "main" {
  for_each = {
    app = {
      instance_types = [local.eks_node_instance]
      desired_size   = local.eks_node_count
    }
  }

  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "${var.environment}-ng-${each.key}"
  node_role_arn   = aws_iam_role.eks_nodes.arn
  subnet_ids      = aws_subnet.private[*].id

  scaling_config {
    desired_size = each.value.desired_size
    min_size     = 1
    max_size     = each.value.desired_size * 2
  }

  instance_types = each.value.instance_types

  # Break circular dependency: EKS cluster must be fully created before node group joins
  depends_on = [aws_eks_cluster.main, aws_iam_role.eks_nodes]
}

# =============================================================================
# IAM SERVICE ACCOUNT (OIDC for prod, programmatic for dev)
# =============================================================================
resource "aws_iam_openid_connect_provider" "eks" {
  client_id_list = ["sts.amazonaws.com"]
  thumbprints    = [aws_eks_cluster.main.identity[0].oidc[0].issuer]
  url            = aws_eks_cluster.main.identity[0].oidc[0].issuer
}

resource "aws_iam_role" "app_service" {
  name = "${var.environment}-app-service-role"
  assume_role_policy = local.is_prod ? jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Federated = aws_iam_role.eks_nodes.arn } # Simplified trust
      Action   = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "${aws_eks_cluster.main.identity[0].oidc[0].issuer}:sub" = "system:serviceaccount:default:app-sa"
        }
      }
    }]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [{ Effect = "Allow", Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }, Action = "sts:AssumeRole" }]
  })
}

resource "aws_iam_role_policy" "app_service" {
  name = "${var.environment}-app-service-policy"
  role = aws_iam_role.app_service.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = local.is_prod ? ["s3:GetObject", "s3:PutObject", "s3:ListBucket"] : ["s3:*"]
      Resource = [aws_s3_bucket.assets.arn, "${aws_s3_bucket.assets.arn}/*"]
    }]
  })
}

data "aws_caller_identity" "current" {}

# =============================================================================
# HTTPS EXPOSURE (ALB for dev, CloudFront+ACM for prod)
# =============================================================================
# Dev: Internal ALB
resource "aws_lb" "app_dev" {
  count = local.is_prod ? 0 : 1
  name  = "${var.environment}-internal-alb"
  internal = true
  load_balancer_type = "application"
  subnets = aws_subnet.private[*].id
  tags = { Environment = var.environment }
}

resource "aws_lb_listener" "app_dev" {
  count           = local.is_prod ? 0 : 1
  load_balancer_arn = aws_lb.app_dev[0].arn
  port            = 443
  protocol        = "HTTPS"
  ssl_policy      = "ELBSecurityPolicy-2016-08"
  certificate_arn = "arn:aws:acm:${var.region}:${data.aws_caller_identity.current.account_id}:certificate/dev-placeholder"

  default_action {
    type       = "forward"
    target_group_arn = aws_lb_target_group.app_dev[0].arn
  }
}

resource "aws_lb_target_group" "app_dev" {
  count = local.is_prod ? 0 : 1
  name  = "${var.environment}-tg"
  port  = 80
  protocol = "HTTP"
  vpc_id = aws_vpc.main.id
  target_type = "ip"
}

# Prod: CloudFront + ACM
resource "aws_acm_certificate" "prod" {
  count            = local.is_prod ? 1 : 0
  domain_name      = "app.${var.environment}.example.com"
  validation_method = "DNS"
}

resource "aws_cloudfront_distribution" "prod" {
  count = local.is_prod ? 1 : 0
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Prod App Distribution"
  default_root_object = "index.html"

  origin {
    domain_name = aws_lb.app_prod[0].dns_name
    origin_id   = "alb-origin"
    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  viewer_certificate {
    acm_certificate_arn = aws_acm_certificate.prod[0].arn
    ssl_support_method  = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  default_cache_behavior {
    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]
    target_origin_id = "alb-origin"
    viewer_protocol_policy = "redirect-to-https"
    compress              = true
  }
}

# Prod ALB (origin for CloudFront)
resource "aws_lb" "app_prod" {
  count = local.is_prod ? 1 : 0
  name  = "${var.environment}-alb"
  internal = false
  load_balancer_type = "application"
  subnets = aws_subnet.private[*].id
  tags = { Environment = var.environment }
}

resource "aws_lb_target_group" "app_prod" {
  count = local.is_prod ? 1 : 0
  name  = "${var.environment}-tg"
  port  = 80
  protocol = "HTTP"
  vpc_id = aws_vpc.main.id
  target_type = "ip"
}

# =============================================================================
# SECRETS (SOPS-encrypted)
# =============================================================================
data "sops_file" "db_secret" {
  source = var.db_sops_file
  # SOPS provider automatically decrypts using configured keys (AGE/PGP/KMS)
}
```

---

### 📜 `outputs.tf`
```hcl
output "rds_endpoint" {
  value       = aws_db_instance.app.endpoint
  sensitive   = true
  description = "RDS PostgreSQL connection endpoint"
}

output "eks_cluster_endpoint" {
  value       = aws_eks_cluster.main.endpoint
  description = "EKS API server endpoint"
}

output "s3_bucket_name" {
  value       = aws_s3_bucket.assets.bucket
  description = "Application assets S3 bucket name"
}

output "https_endpoint" {
  value       = local.is_prod ? aws_cloudfront_distribution.prod[0].domain_name : aws_lb.app_dev[0].dns_name
  description = "Public HTTPS endpoint"
}
```

---

### 🛠️ Key Fixes Explained

#### 1. 🔄 Circular Dependency Fix
**Symptom:** `Error: Cycle: aws_eks_cluster.main, aws_eks_node_group.main, aws_iam_role.eks_nodes`
**Root Cause:** Terraform cannot resolve implicit dependencies when resources reference each other across data sources or when `data` triggers are evaluated before resource creation.
**Fix Applied:**
- Explicit `depends_on = [aws_eks_cluster.main, aws
